+import Ajv from 'ajv';
+import type {ErrorObject, ValidateFunction} from 'ajv';
 import type {ToolDefinition} from '../../types/ai.js';
 import type {OutgoingMessage} from '../../types/messages.js';
 import {log} from '../../shared/logger.js';
@@ -83,6 +83,12 @@ export class ToolRegistry {
       log.warn('tool', 'tool not found', {name});
       throw new Error(`Unknown tool: ${name}`);
     }
+    if (!tool.validateInput(input)) {
+      const errors = tool.validateInput.errors ?? [];
+      const detail = errors.map(describeViolation).join('; ');
+      log.warn('tool', 'input rejected by inputSchema', {name, detail});
+      return {result: `Tool "${name}" rejected input: ${detail}`};
+    }
     log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
     const rawResult = await tool.execute(input, context);
     const response = normalizeToolResponse(rawResult);
@@ -103,6 +109,12 @@ function compileSchema(toolName: string, schema: Record<string, unknown>): Valid
   try {
     return ajv.compile(schema);
   } catch (error) {
-    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`);
+    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
   }
 }
+
+// ajv messages carry the path and the failed constraint but never the input value, so both sinks can quote them.
+function describeViolation(error: ErrorObject): string {
+  const path = error.instancePath === '' ? 'input' : error.instancePath;
+  return `${path} ${error.message} (${error.keyword})`;
+}

